BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS helpdesk;
CREATE TABLE IF NOT EXISTS helpdesk.routing_queues (queue_key text PRIMARY KEY CHECK (queue_key ~ '^[a-z_]+$'), display_name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO helpdesk.routing_queues(queue_key,display_name) VALUES ('security_response','Security Response'),('technical_support','Technical Support'),('account_support','Account Support'),('billing_support','Billing Support'),('product_feedback','Product Feedback'),('general_support','General Support'),('manual_review','Manual Review') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS helpdesk.sla_policies (policy_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), priority text NOT NULL CHECK(priority IN ('P1','P2','P3','P4')), business_minutes integer NOT NULL CHECK(business_minutes>0), business_hours boolean NOT NULL DEFAULT true, timezone text NOT NULL DEFAULT 'Asia/Manila', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(priority,active));
INSERT INTO helpdesk.sla_policies(priority,business_minutes,business_hours) VALUES ('P1',240,false),('P2',480,true),('P3',960,true),('P4',2400,true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS helpdesk.tickets (ticket_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), idempotency_key char(64) NOT NULL UNIQUE, requester_email text NOT NULL, subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 200), description text NOT NULL CHECK(length(description) BETWEEN 1 AND 10000), status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','processing','routed','manual_review','failed')), category text CHECK(category IN ('account','billing','technical','security','feature_request','general','unknown')), priority text CHECK(priority IN ('P1','P2','P3','P4')), assigned_queue text REFERENCES helpdesk.routing_queues(queue_key), confidence numeric(3,2) CHECK(confidence BETWEEN 0 AND 1), needs_human_review boolean NOT NULL DEFAULT false, sla_deadline timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tickets_status_queue_idx ON helpdesk.tickets(status,assigned_queue); CREATE INDEX IF NOT EXISTS tickets_sla_idx ON helpdesk.tickets(sla_deadline);
CREATE TABLE IF NOT EXISTS helpdesk.ticket_events (event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES helpdesk.tickets(ticket_id), event_type text NOT NULL, actor text NOT NULL, correlation_id uuid NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ticket_events_ticket_time_idx ON helpdesk.ticket_events(ticket_id,created_at);
CREATE TABLE IF NOT EXISTS helpdesk.classification_runs (run_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES helpdesk.tickets(ticket_id), model_name text NOT NULL, prompt_version text NOT NULL, result jsonb, valid boolean NOT NULL DEFAULT false, confidence numeric(3,2), latency_ms integer, retry_count integer NOT NULL DEFAULT 0, failure_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS helpdesk.notification_outbox (outbox_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES helpdesk.tickets(ticket_id), idempotency_key char(64) NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')), attempts integer NOT NULL DEFAULT 0, last_error_code text, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE IF NOT EXISTS helpdesk.failed_jobs (failed_job_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid REFERENCES helpdesk.tickets(ticket_id), stage text NOT NULL, failure_class text NOT NULL CHECK(failure_class IN ('retryable','non_retryable','human_review','terminal')), error_code text NOT NULL, attempt_count integer NOT NULL DEFAULT 0, next_retry_at timestamptz, terminal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS failed_jobs_retry_idx ON helpdesk.failed_jobs(terminal,next_retry_at);
COMMIT;
